import{_ as a,c as i,a0 as s,o as t}from"./chunks/framework.B6JXc2q-.js";const u=JSON.parse('{"title":"Auth 运行时恢复实现与观测参考","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/auth_runtime_recovery.md","filePath":"architecture/auth_runtime_recovery.md"}'),n={name:"architecture/auth_runtime_recovery.md"};function o(l,e,d,c,r,p){return t(),i("div",null,e[0]||(e[0]=[s(`<h1 id="auth-运行时恢复实现与观测参考" tabindex="-1">Auth 运行时恢复实现与观测参考 <a class="header-anchor" href="#auth-运行时恢复实现与观测参考" aria-label="Permalink to &quot;Auth 运行时恢复实现与观测参考&quot;">​</a></h1><blockquote><p>本文描述当前认证状态机主线的实现与观测，不绑定短期 commit；它不替代 <a href="./../spec/auth/auth_runtime_recovery.html"><code>docs/spec/auth/auth_runtime_recovery.md</code></a> 的验收规范。</p></blockquote><h2 id="_1-实现边界" tabindex="-1">1. 实现边界 <a class="header-anchor" href="#_1-实现边界" aria-label="Permalink to &quot;1. 实现边界&quot;">​</a></h2><p>认证运行时分三层：</p><ol><li><strong>persistent auth</strong>：最小能力为 <code>userId</code>、<code>passToken</code>、<code>deviceId</code>；<code>psecurity</code>、<code>ssecurity</code>、<code>cUserId</code> 仅作诊断/兼容字段。</li><li><strong>short session</strong>：<code>serviceToken</code>、<code>yetAnotherServiceToken</code>。</li><li><strong>runtime</strong>：<code>login_account</code>、<code>mina_service</code>、<code>miio_service</code>、session、cookie 和签名。</li></ol><p><code>TokenStore</code>/<code>conf/auth.json</code> 是持久认证事实来源。env credential 是运行时覆盖， 不属于持久事实，禁止写回磁盘。</p><p>当前 primary 观测值为 <code>miaccount_persistent_auth_exchange</code>：它表示 <code>passToken → serviceToken</code> exchange via <code>serviceLogin</code>，不是 <code>MiAccount.login</code>。</p><h2 id="_2-认证入口" tabindex="-1">2. 认证入口 <a class="header-anchor" href="#_2-认证入口" aria-label="Permalink to &quot;2. 认证入口&quot;">​</a></h2><h3 id="_2-1-ensure-auth-try-login" tabindex="-1">2.1 <code>ensure_auth()</code> / <code>_try_login()</code> <a class="header-anchor" href="#_2-1-ensure-auth-try-login" aria-label="Permalink to &quot;2.1 \`ensure_auth()\` / \`_try_login()\`&quot;">​</a></h3><p><code>ensure_auth()</code> 先做 runtime probe。probe 失败后，<code>_try_login()</code> 在 transition lock 内按以下顺序工作：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>读取 auth_data</span></span>
<span class="line"><span>  -&gt; env override？runtime rebind/verify（不换票）</span></span>
<span class="line"><span>  -&gt; mina_service 缺失？尝试 persisted short-session fast rebind/verify</span></span>
<span class="line"><span>  -&gt; 完整 persistent auth？atomic short-session rebuild</span></span>
<span class="line"><span>  -&gt; 没有明确 persistent capability 时，才允许进入显式 full-login 场景</span></span></code></pre></div><p><strong>自然过期边界</strong>：即使磁盘仍保留旧 <code>serviceToken</code>，只要完整 persistent auth 存在， fast rebind 未成功后仍必须走 atomic rebuild；atomic 失败绝不能落到无口令 <code>MiAccount.login</code>。</p><p>完整无口令 login 不是 scheduled、manual、persistent-auth recovery 的 fallback。</p><h3 id="_2-2-scheduled-refresh" tabindex="-1">2.2 Scheduled refresh <a class="header-anchor" href="#_2-2-scheduled-refresh" aria-label="Permalink to &quot;2.2 Scheduled refresh&quot;">​</a></h3><p><code>_maybe_scheduled_refresh()</code>：</p><ul><li>若持久 token 有明确、有效、正数的 <code>expires_in</code>，以 <code>saveTime + expires_in</code> 计算 TTL，使用 <code>auth_refresh_threshold</code>（安全夹在 <code>0.01..0.99</code>）按剩余比例触发，日志模式为 <code>ttl_ratio</code>。</li><li>若 <code>expires_in</code> 缺失或无效，不伪造 TTL；以 <code>auth_refresh_interval_hours</code> （安全正数下限 <code>0.01</code> 小时，默认 <code>12</code> 小时）作为固定刷新间隔，按持久 <code>saveTime</code> 计算 elapsed，日志模式为 <code>interval_fallback</code>，此路径不再乘阈值。</li><li>runtime probe 成功不会更新 TTL 锚点或 <code>saveTime</code>。</li><li>env override 直接记录 <code>scheduled_env_override_skip</code> 并返回。</li><li>无 persistent capability 记录 capability skip。</li><li>其他情况调用：</li></ul><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> rebuild_short_session_from_persistent_auth(</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    reason</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;_maybe_scheduled_refresh&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    atomic</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">True</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>scheduled 失败不修改仍健康 runtime；attempt timestamp 独立负责 cooldown。</p><h3 id="_2-3-manual-reload" tabindex="-1">2.3 Manual reload <a class="header-anchor" href="#_2-3-manual-reload" aria-label="Permalink to &quot;2.3 Manual reload&quot;">​</a></h3><p><code>manual_reload_runtime()</code>：</p><ol><li>有 TokenStore 时先调用 <code>reload_from_disk()</code>。</li><li>env 模式调用当前 auth data 的 atomic runtime rebind/verify；不调用 <code>_serviceLogin</code>、不调用 <code>MiAccount.login</code>、不写 token。</li><li>非 env 模式调用 atomic persistent refresh。</li><li>verified success 清理 manual login gate；fatal 失败映射到 <code>manual_login_required</code>。</li></ol><p>返回中的 <code>token_store_reloaded</code> 只有真实执行 <code>reload_from_disk()</code> 后才能为 true。 <code>runtime_swap_attempted</code> 只在结果明确表示尝试时为 true，缺省/<code>None</code>/<code>skipped</code> 均为 false。</p><h2 id="_3-atomic-rebuild-实现" tabindex="-1">3. Atomic rebuild 实现 <a class="header-anchor" href="#_3-atomic-rebuild-实现" aria-label="Permalink to &quot;3. Atomic rebuild 实现&quot;">​</a></h2><p>入口默认值为：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">rebuild_short_session_from_persistent_auth(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">reason</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">atomic</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">True</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>生产入口均显式使用 <code>atomic=True</code>。<code>atomic=False</code> 仅为 legacy 兼容路径。</p><h3 id="_3-1-candidate-pipeline" tabindex="-1">3.1 Candidate pipeline <a class="header-anchor" href="#_3-1-candidate-pipeline" aria-label="Permalink to &quot;3.1 Candidate pipeline&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>persistent auth snapshot</span></span>
<span class="line"><span>  -&gt; _try_miaccount_persistent_auth_relogin(writeback=False)</span></span>
<span class="line"><span>  -&gt; candidate auth data</span></span>
<span class="line"><span>  -&gt; _build_verified_runtime_candidate(candidate_auth_data)</span></span>
<span class="line"><span>  -&gt; candidate device_list verify</span></span>
<span class="line"><span>  -&gt; TokenStore.commit(candidate_auth_data)（env 时跳过）</span></span>
<span class="line"><span>  -&gt; 一次性同步 runtime 引用</span></span>
<span class="line"><span>  -&gt; generation += 1</span></span>
<span class="line"><span>  -&gt; await close old session</span></span></code></pre></div><p>candidate verify 失败时：</p><ul><li>不调用 TokenStore.commit</li><li>不更新 <code>saveTime</code></li><li>不替换旧 runtime</li><li>不关闭仍在使用的旧 session</li></ul><p>TokenStore commit 失败时同样保留旧 token 镜像和旧 runtime。</p><h3 id="_3-2-runtime-一次性提交" tabindex="-1">3.2 Runtime 一次性提交 <a class="header-anchor" href="#_3-2-runtime-一次性提交" aria-label="Permalink to &quot;3.2 Runtime 一次性提交&quot;">​</a></h3><p>下列引用在任何 close await 前同步完成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>device_id</span></span>
<span class="line"><span>login_account</span></span>
<span class="line"><span>mina_service</span></span>
<span class="line"><span>miio_service</span></span>
<span class="line"><span>mi_session</span></span>
<span class="line"><span>cookie_jar</span></span>
<span class="line"><span>login_signature</span></span>
<span class="line"><span>_runtime_generation</span></span></code></pre></div><p>旧 session 只在新 runtime 完整可见后关闭。取消 close await 不会造成新 session+旧 service 的半提交状态。</p><h3 id="_3-3-tokenstore-commit" tabindex="-1">3.3 TokenStore commit <a class="header-anchor" href="#_3-3-tokenstore-commit" aria-label="Permalink to &quot;3.3 TokenStore commit&quot;">​</a></h3><p><code>TokenStore.commit()</code> 持锁工作：</p><ul><li><code>persist_token=true</code>：原子文件替换成功后才更新 <code>_token/_dirty/_loaded</code>。</li><li><code>persist_token=false</code>：明确为仅内存提交，不写磁盘且不保留 dirty。</li><li>异常时内存镜像三字段保持原值。</li></ul><p>历史 <code>update()+flush()</code> 仍可被兼容代码使用，但不是 atomic 主路径。</p><h2 id="_4-persistent-relogin-与-session" tabindex="-1">4. Persistent relogin 与 session <a class="header-anchor" href="#_4-persistent-relogin-与-session" aria-label="Permalink to &quot;4. Persistent relogin 与 session&quot;">​</a></h2><p><code>_try_miaccount_persistent_auth_relogin()</code> 只返回候选 token 数据和分类结果，不把 创建的 ClientSession 交给 runtime。TypeError legacy constructor 路径也会关闭创建的 session。</p><p>serviceLogin 非零 code 分类：</p><ul><li><code>70016</code>：<code>credential_session_rejected</code>。</li><li><code>87001</code> 或 <code>captchaUrl</code>：<code>interactive_captcha_challenge</code>。</li><li>两类均 <code>long_term_expired=false</code>；无头恢复可 <code>need_qr_scan/user_action_required=true</code>。</li><li>未知非零 code，例如 <code>10001</code>、<code>500</code>：可属于 auth error，但不自动推断需要扫码。</li><li><code>service_login_failed</code> 和 <code>service_login_code_*</code> 是 auth 域错误标签，不等于长期失效。</li></ul><h2 id="_5-fatal-manual-gate" tabindex="-1">5. Fatal manual gate <a class="header-anchor" href="#_5-fatal-manual-gate" aria-label="Permalink to &quot;5. Fatal manual gate&quot;">​</a></h2><p>fatal 分类首次失败即进入持久 manual gate：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>state = LOCKED</span></span>
<span class="line"><span>_last_manual_login_required_reason != &quot;&quot;</span></span>
<span class="line"><span>locked_until 不作为人工 gate 的过期条件</span></span></code></pre></div><p>非 force <code>ensure_auth()</code> 在 probe 前短路，不重复访问小米服务。</p><p>verified runtime recovery 成功统一调用内部 success helper：</p><ul><li>state=<code>HEALTHY</code></li><li><code>locked_until=0</code></li><li>清空 <code>_last_manual_login_required_reason</code></li><li>清空 lock transition reason</li></ul><p>失败恢复不调用该 helper。<code>clear_auth_lock()</code> 仍是显式人工/二维码成功入口。</p><h2 id="_6-transition-lock-与-generation" tabindex="-1">6. Transition lock 与 generation <a class="header-anchor" href="#_6-transition-lock-与-generation" aria-label="Permalink to &quot;6. Transition lock 与 generation&quot;">​</a></h2><p><code>_auth_transition_lock</code> 覆盖候选快照、verify、commit、runtime swap 的事务边界。</p><p>调用者等待 lock 前保存 generation；获得 lock 后：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>若 generation 已变化</span></span>
<span class="line"><span>且当前 state=HEALTHY</span></span>
<span class="line"><span>且 runtime ready</span></span>
<span class="line"><span>=&gt; 复用前一个成功事务，不重复 login/rebuild</span></span></code></pre></div><p>generation 只在 verified runtime 成功提交后递增。reason 字符串不参与判断。</p><h2 id="_7-时间与观测字段" tabindex="-1">7. 时间与观测字段 <a class="header-anchor" href="#_7-时间与观测字段" aria-label="Permalink to &quot;7. 时间与观测字段&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>语义</th><th>不得承担的语义</th></tr></thead><tbody><tr><td><code>_last_session_success_ts</code></td><td>session 建立/刷新成功</td><td>不作 health probe 或 cooldown</td></tr><tr><td><code>_last_runtime_verify_ts</code></td><td>runtime 验证成功</td><td>不延长 token TTL</td></tr><tr><td><code>_last_refresh_attempt_ts</code></td><td>scheduled 尝试/skip</td><td>不代表 token 成功</td></tr><tr><td><code>TokenStore.saveTime</code></td><td>持久 token 发行/刷新事实</td><td>不被 probe 时间覆盖</td></tr></tbody></table><p>相关 debug flow：</p><ul><li><code>started_at</code> / <code>finished_at</code></li><li><code>primary_attempt</code></li><li><code>fallback_attempt</code>（scheduled atomic 中明确 skipped）</li><li><code>rebind</code></li><li><code>verify</code></li><li><code>result</code></li></ul><p>primary token exchange 成功但 candidate verify 失败时，必须显示：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>primary_attempt.result = ok</span></span>
<span class="line"><span>verify.result = failed</span></span></code></pre></div><h2 id="_8-公共状态映射" tabindex="-1">8. 公共状态映射 <a class="header-anchor" href="#_8-公共状态映射" aria-label="Permalink to &quot;8. 公共状态映射&quot;">​</a></h2><p><code>map_auth_public_status()</code> 的重点结果：</p><ul><li>persistent auth 缺失：<code>persistent_auth_missing</code></li><li>short-session rebuild 失败：<code>short_session_rebuild_failed</code></li><li>runtime 未准备：<code>runtime_not_ready</code></li><li>fatal auth + manual gate：<code>manual_login_required</code></li><li>健康：<code>healthy</code> / <code>status=ok</code></li></ul><p>Reactive/manual reload 的 70016/87001 首次失败即为 <code>manual_login_required</code>，但 <code>long_term_expired=false</code>；未知 serviceLogin 非零 code 不得误报扫码。</p><p>Scheduled 的两类错误保持 public healthy，设置 <code>scheduled_refresh_suspended</code> 及原因； 后续周期零网络，verified recovery 才清除挂起。</p><h2 id="_9-代码定位" tabindex="-1">9. 代码定位 <a class="header-anchor" href="#_9-代码定位" aria-label="Permalink to &quot;9. 代码定位&quot;">​</a></h2><ul><li><code>xiaomusic/auth.py</code><ul><li><code>ensure_auth()</code> / <code>_try_login()</code></li><li><code>_maybe_scheduled_refresh()</code></li><li><code>rebuild_short_session_from_persistent_auth()</code></li><li><code>_atomic_persistent_auth_refresh()</code></li><li><code>_atomic_runtime_rebind_current_auth()</code></li><li><code>_try_miaccount_persistent_auth_relogin()</code></li><li><code>manual_reload_runtime()</code></li></ul></li><li><code>xiaomusic/security/token_store.py</code><ul><li><code>TokenStore.commit()</code></li><li><code>TokenStore.reload_from_disk()</code></li></ul></li><li>观测端点：<code>/api/v1/auth/status</code> 与 <code>/api/v1/debug/auth_*</code></li></ul>`,68)]))}const _=a(n,[["render",o]]);export{u as __pageData,_ as default};
